package com.example.battleshipgame.logic;
public class GameEngine {public final Board player,computer;public final SpecialPowers powers=new SpecialPowers();private boolean playerTurn=true;public GameEngine(){this(new Board());player.placeRandomFleet();}public GameEngine(Board playerBoard){player=playerBoard;computer=new Board();computer.placeRandomFleet();}public boolean isPlayerTurn(){return playerTurn;}public ShotResult playerShot(int r,int c){if(!playerTurn)return ShotResult.ALREADY_SHOT;ShotResult s=computer.shoot(r,c);if(s==ShotResult.HIT||s==ShotResult.SUNK)powers.addHit();if(s==ShotResult.MISS)playerTurn=false;return s;}public ShotResult computerShot(int r,int c){ShotResult s=player.shoot(r,c);if(s==ShotResult.MISS)playerTurn=true;return s;}public boolean isOver(){return player.allSunk()||computer.allSunk();}}
